<?php
require_once __DIR__.'/_bootstrap.php'; requireMethod('POST'); $u=requireUser(); $b=requestBody(); $p=$b['profile']??null; $best=$b['best']??null; if (!is_array($p)||!is_array($best)) jsonResponse(400,['ok'=>false,'error'=>'A profile and best-score object are required.']);
$profile=['runs'=>clampInt($p['runs']??0,0,1000000000),'kills'=>clampInt($p['kills']??0,0,1000000000),'highestLevel'=>clampInt($p['highestLevel']??1,1,1000000,1)]; $best=['wave'=>clampInt($best['wave']??0,0,1000000),'score'=>clampInt($best['score']??0,0,2000000000)]; $pdo=null;
try { $pdo=db(); $pdo->beginTransaction(); $s=$pdo->prepare('SELECT profile_json,best_json FROM public.player_saves WHERE user_id=:id FOR UPDATE'); $s->execute(['id'=>$u['id']]); $old=$s->fetch(); if ($old) { $op=is_array($old['profile_json'])?$old['profile_json']:json_decode((string)$old['profile_json'],true); $ob=is_array($old['best_json'])?$old['best_json']:json_decode((string)$old['best_json'],true); if (is_array($op)) foreach(['runs','kills','highestLevel'] as $k) $profile[$k]=max($profile[$k],(int)($op[$k]??0)); if (is_array($ob)) foreach(['wave','score'] as $k) $best[$k]=max($best[$k],(int)($ob[$k]??0)); }
$sql='INSERT INTO public.player_saves (user_id,profile_json,best_json,updated_at) VALUES (:id,CAST(:p AS jsonb),CAST(:b AS jsonb),CURRENT_TIMESTAMP) ON CONFLICT (user_id) DO UPDATE SET profile_json=EXCLUDED.profile_json,best_json=EXCLUDED.best_json,updated_at=CURRENT_TIMESTAMP RETURNING updated_at'; $s=$pdo->prepare($sql); $s->execute(['id'=>$u['id'],'p'=>json_encode($profile,JSON_THROW_ON_ERROR),'b'=>json_encode($best,JSON_THROW_ON_ERROR)]); $savedAt=$s->fetchColumn(); $pdo->commit(); jsonResponse(200,['ok'=>true,'profile'=>$profile,'best'=>$best,'savedAt'=>$savedAt]); }
catch(Throwable $e) { if ($pdo instanceof PDO && $pdo->inTransaction()) $pdo->rollBack(); error_log('[Bastion save] '.$e->getMessage()); jsonResponse(500,['ok'=>false,'error'=>'Could not save game progress.']); }
